INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7662099, 1248642, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2020-05-10 11:01:24.000000', NULL, 1),
(7662124, 1248991, 96815, '<td valign="top">This is either a pinhole lens made with ultra precision to get that sharp... or it''s not a pinhole. Either way, this image doesn''t do much for me. The crop is too tight on the subjects, the background is too busy, and there is some wild hair coming into the frame that''s pretty distracting.</td>', 'This is either a pinhole lens made with ultra precision to get that sharp... or it''s not a pinhole. Either way, this image doesn''t do much for me. The crop is too tight on the subjects, the background is too busy, and there is some wild hair coming into the frame that''s pretty distracting.', '2020-05-10 12:31:23.000000', NULL, 1),
(7662125, 1248642, 96815, '<td valign="top">The shallow depth of field here doesn''t compute with a pinhole camera, or even a ''pinhole effect''. The image outside of this challenge is fairly nice.</td>', 'The shallow depth of field here doesn''t compute with a pinhole camera, or even a ''pinhole effect''. The image outside of this challenge is fairly nice.', '2020-05-10 12:31:42.000000', NULL, 1),
(7662126, 1249161, 96815, '<td valign="top">It looks like a real pinhole! I wonder if that subject was the only thing you could find with enough brightness at the time. Lacks interest, +1 for making a pinhole though.</td>', 'It looks like a real pinhole! I wonder if that subject was the only thing you could find with enough brightness at the time. Lacks interest, +1 for making a pinhole though.', '2020-05-10 12:33:50.000000', NULL, 1),
(7662127, 1249121, 96815, '<td valign="top">From my experiments, pinholes don''t actually have a heavy vignette like that so I am leaning toward this being made using a glass lens, but not totally sure. Regardless, you have the effect with the infinite depth of field and ''dreamy look'', but not much here from a composition standpoint. Nice family!</td>', 'From my experiments, pinholes don''t actually have a heavy vignette like that so I am leaning toward this being made using a glass lens, but not totally sure. Regardless, you have the effect with the infinite depth of field and ''dreamy look'', but not much here from a composition standpoint. Nice family!', '2020-05-10 12:39:58.000000', NULL, 1),
(7662128, 1249140, 96815, '<td valign="top">It looks like a real pinhole image to me! I think your hole size may be on the larger side resulting in the heavy blur. My first attempts yielded similar results until I tried again with a hole barely visible pricked into a pop can. That resulted in something somewhat sharp. Although the composition is pretty plain, I like it.</td>', 'It looks like a real pinhole image to me! I think your hole size may be on the larger side resulting in the heavy blur. My first attempts yielded similar results until I tried again with a hole barely visible pricked into a pop can. That resulted in something somewhat sharp. Although the composition is pretty plain, I like it.', '2020-05-10 12:44:04.000000', NULL, 1),
(7662129, 1249153, 96815, '<td valign="top">It looks like a real pinhole image to me! I think your hole size may be on the larger side resulting in the heavy blur. My first attempts yielded similar results until I tried again with a hole barely visible pricked into a pop can. That resulted in something somewhat sharp. All in all, a decent portrait given the equipment used.</td>', 'It looks like a real pinhole image to me! I think your hole size may be on the larger side resulting in the heavy blur. My first attempts yielded similar results until I tried again with a hole barely visible pricked into a pop can. That resulted in something somewhat sharp. All in all, a decent portrait given the equipment used.', '2020-05-10 12:45:52.000000', NULL, 1),
(7662130, 1249123, 96815, '<td valign="top">Don''t look now, but your aperture blades are showing...</td>', 'Don''t look now, but your aperture blades are showing...', '2020-05-10 12:47:08.000000', NULL, 1),
(7662136, 1249068, 96815, '<td valign="top">Looks like a real pinhole to me! The effect really works for this image. It gives it an eerie feel. Nice composition too.</td>', 'Looks like a real pinhole to me! The effect really works for this image. It gives it an eerie feel. Nice composition too.', '2020-05-10 13:05:20.000000', NULL, 1),
(7662137, 1249106, 96815, '<td valign="top">I''m not sure where this is... but I remember seeing this guy in that past. The flare from the sun looks just like the flares I saw when experimenting so it looks real to me! Nice composition, colours, and dreamy feel. Well done.</td>', 'I''m not sure where this is... but I remember seeing this guy in that past. The flare from the sun looks just like the flares I saw when experimenting so it looks real to me! Nice composition, colours, and dreamy feel. Well done.', '2020-05-10 13:07:40.000000', NULL, 1),
(7662145, 1248991, 60581, '<td valign="top">Interesting shot and good to the see two of them!</td>', 'Interesting shot and good to the see two of them!', '2020-05-10 14:28:07.000000', NULL, 1),
(7662146, 1248642, 60581, '<td valign="top">Looking at this shot, yes I can see that there is pin hole involved but the sharpness on the tip the flowers won''t be able to achieve with just pinhole. I have a feeling that this was taken with the lens on and on top pinhole was put it in. In case if I am wrong then "I would love to know the setup as to get the sharp image" :)</td>', 'Looking at this shot, yes I can see that there is pin hole involved but the sharpness on the tip the flowers won''t be able to achieve with just pinhole. I have a feeling that this was taken with the lens on and on top pinhole was put it in. In case if I am wrong then "I would love to know the setup as to get the sharp image" :)', '2020-05-10 14:30:04.000000', NULL, 1),
(7662147, 1249068, 60581, '<td valign="top">Interesting bokeh in this image and I am scratching my head to see how that bokeh would have come..nice shot!</td>', 'Interesting bokeh in this image and I am scratching my head to see how that bokeh would have come..nice shot!', '2020-05-10 14:31:52.000000', NULL, 1),
(7662149, 1249158, 60581, '<td valign="top">yup something like this can be achieved with just pinhole, I played around a lot with this and I believe I know how to get this now :D</td>', 'yup something like this can be achieved with just pinhole, I played around a lot with this and I believe I know how to get this now :D', '2020-05-10 14:39:44.000000', NULL, 1),
(7662335, 1249085, 124815, '<td valign="top">Triplet Tom is a treat!</td>', 'Triplet Tom is a treat!', '2020-05-11 19:13:03.000000', NULL, 1),
(7662336, 1248567, 124815, '<td valign="top">I don''t know anything about doing a pinhole - but appreciate the quality of an image. This one seems to be a photo of one of the little painted porcelain figurine with applied filters - so I will not vote</td>', 'I don''t know anything about doing a pinhole - but appreciate the quality of an image. This one seems to be a photo of one of the little painted porcelain figurine with applied filters - so I will not vote', '2020-05-11 19:20:24.000000', NULL, 1),
(7662344, 1249156, 32948, '<td valign="top">Nice sky, and movement which was always an effect with Pinhole cams.</td>', 'Nice sky, and movement which was always an effect with Pinhole cams.', '2020-05-11 21:49:42.000000', NULL, 1),
(7662345, 1248991, 32948, '<td valign="top">you got this clarity from a pinhole? gotta know the secret.</td>', 'you got this clarity from a pinhole? gotta know the secret.', '2020-05-11 21:50:42.000000', NULL, 1),
