(7662347, 1249085, 32948, '<td valign="top">That is a great effect.</td>', 'That is a great effect.', '2020-05-11 21:55:58.000000', NULL, 1),
(7662641, 1249167, 100831, '<td valign="top">Someone has a very wild imagination. Cute title!! An image that is so interesting that it stopped me in my tracks.</td>', 'Someone has a very wild imagination. Cute title!! An image that is so interesting that it stopped me in my tracks.', '2020-05-15 15:05:01.000000', NULL, 1),
